9	import { useTranslate } from "@/utils/i18n";
10	import { errorService, memoService, validationService } from "../services";
11	import { useEditorContext } from "../state";
12	
13	interface UseMemoSaveOptions {
14	  memoName?: string;
15	  parentMemoName?: string;
16	  defaultVisibility?: Visibility;
17	  defaultCreateTime?: Date;
18	  discardDraft: () => void;
19	  onConfirm?: (memoName: string) => void;
20	  onCancel?: () => void;
21	}
22	
23	/**
24	 * Owns the editor's save transaction and its post-save cache/state updates.
25	 * Keeping this workflow outside the shell makes saving identical whether it is
26	 * triggered by the toolbar or the editor keyboard shortcut.
27	 */
28	export function useMemoSave({
29	  memoName,
30	  parentMemoName,
31	  defaultVisibility,
32	  defaultCreateTime,
33	  discardDraft,
34	  onConfirm,
35	  onCancel,
36	}: UseMemoSaveOptions): () => Promise<void> {
37	  const t = useTranslate();
38	  const queryClient = useQueryClient();
39	  const { markNewMemo } = useNewMemo();
40	  const { actions, dispatch, getState } = useEditorContext();
41	
42	  return useCallback(async () => {
43	    const state = getState();
44	    const { valid, reason } = validationService.canSave(state);
45	    if (!valid) {
46	      toast.error(reason || "Cannot save");
47	      return;
48	    }
49	
50	    dispatch(actions.setLoading("saving", true));
51	
52	    try {
53	      const result = await memoService.save(state, { memoName, parentMemoName });
54	
55	      if (!result.hasChanges) {
56	        toast.error(t("editor.no-changes-detected"));
57	        onCancel?.();
58	        return;
59	      }
60	
61	      // Prevent the autosave unmount flush from restoring the saved draft.
62	      discardDraft();
63	
64	      const invalidationPromises = [
65	        queryClient.invalidateQueries({ queryKey: memoKeys.lists() }),
66	        queryClient.invalidateQueries({ queryKey: userKeys.stats() }),
67	      ];
68	      if (memoName) {
69	        invalidationPromises.push(queryClient.invalidateQueries({ queryKey: memoKeys.detail(memoName) }));
